data.appointments??=[];data.monthlyFees??={};
let financeTab='agenda',financeMonth=todayKey().slice(0,7),agendaOffset=0,appointmentSound=false,appointmentAudio=null;
const weekdaysFull=['Domingo','Segunda-feira','Terça-feira','Quarta-feira','Quinta-feira','Sexta-feira','Sábado'];
const money=cents=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(cents/100);
const feeFor=(id,month=financeMonth)=>data.monthlyFees[month]?.[id]||{expected:0,received:0,due:10};
function financeTotals(){return visibleStudents().reduce((total,s)=>{const f=feeFor(s.id);total.expected+=f.expected;total.received+=f.received;total.pending+=Math.max(0,f.expected-f.received);return total},{expected:0,received:0,pending:0})}
function feeOverdue(f,month=financeMonth){const days=new Date(Number(month.slice(0,4)),Number(month.slice(5)),0).getDate();const key=`${month}-${String(Math.min(days,f.due)).padStart(2,'0')}`;return key<todayKey()&&f.expected>f.received}
function minutesAt(time){const [hours,minutes]=time.split(':').map(Number);return hours*60+minutes}
function appointmentConflict(value,ignore){return data.appointments.some(a=>ownsStudent(a.student)&&!a.archived&&a.id!==ignore&&a.day===value.day&&minutesAt(a.time)<minutesAt(value.time)+value.duration&&minutesAt(value.time)<minutesAt(a.time)+a.duration)}
function appointmentsOn(key){return data.appointments.filter(a=>!a.archived&&a.day===weekDay(key)&&key>=a.since).sort((a,b)=>a.time.localeCompare(b.time))}
const appointmentName=id=>data.students.find(s=>s.id===id)?.name||'Aluno';
function agendaPanel(){const days=weekDays().map(key=>shiftDay(key,agendaOffset*7));return `<section class="card"><div class="row"><div><span class="eyebrow">ATENDIMENTOS PRESENCIAIS</span><h2>Sua semana, organizada.</h2></div><button class="primary" onclick="editAppointment()">+ Agendar aluno</button></div><div class="agenda-controls"><button aria-label="Semana anterior" onclick="moveAgenda(-1)">←</button><b>${days[0].slice(8)}/${days[0].slice(5,7)} a ${days[6].slice(8)}/${days[6].slice(5,7)}</b><button aria-label="Próxima semana" onclick="moveAgenda(1)">→</button><button onclick="agendaOffset=0;render()">Hoje</button></div><div class="agenda-week">${days.map(key=>`<section class="agenda-day ${key===todayKey()?'current-day':''}"><h3>${weekdaysFull[weekDay(key)]}</h3><p>${key.split('-').reverse().join('/')}</p>${appointmentsOn(key).map(a=>`<article class="appointment"><b>${a.time} <small>· ${a.duration} min</small></b><p>${esc(appointmentName(a.student))}</p><small>${esc(a.location||'Local não informado')}</small><div><button onclick="editAppointment('${a.id}')">Editar</button><button onclick="archiveAppointment('${a.id}')">Cancelar agenda</button></div></article>`).join('')||'<span class="muted">Sem atendimento</span>'}</section>`).join('')}</div><p class="note">Programação semanal recorrente, a partir da data escolhida. Avisos aparecem 15 minutos antes com o app aberto, no horário de Brasília.</p><button aria-pressed="${appointmentSound}" onclick="enableAppointmentSound()">${appointmentSound?'✓ Som dos lembretes ativo':'Ativar som dos lembretes'}</button></section>`}
function financeChart(){const max=Math.max(1,...visibleStudents().map(s=>feeFor(s.id).expected));return `<div class="income-chart" role="img" aria-label="Valores previstos e recebidos por aluno em ${financeMonth}">${visibleStudents().map(s=>{const f=feeFor(s.id);return `<div class="income-row"><div class="row"><b>${esc(s.name)}</b><span>${money(f.expected)}</span></div><div class="income-track"><div class="income-expected" style="width:${f.expected/max*100}%"><div class="income-received" style="width:${f.expected?f.received/f.expected*100:0}%"></div></div></div><small>Recebido: ${money(f.received)} · A receber: ${money(Math.max(0,f.expected-f.received))}</small></div>`}).join('')}</div><div class="chart-legend"><span>▰ Verde: recebido</span><span>▰ Cinza: a receber</span></div>`}
function monthlyPanel(){const t=financeTotals();return `<div class="row month-selection"><label>Mês de acompanhamento<input type="month" aria-label="Mês financeiro" value="${financeMonth}" onchange="setFinanceMonth(this.value)"></label><button class="primary" onclick="editFee()">+ Definir valor por aluno</button></div><div class="grid stats"><div class="card stat"><p>Receita prevista</p><strong>${money(t.expected)}</strong><small>Valores cadastrados neste mês</small></div><div class="card stat"><p>Recebido</p><strong>${money(t.received)}</strong><small>Pagamentos registrados manualmente</small></div><div class="card stat"><p>A receber</p><strong>${money(t.pending)}</strong><small>Previsto menos recebido</small></div></div><section class="card"><h2>Ganhos mensais por aluno</h2>${financeChart()}</section><section class="card fee-list"><h2>Mensalidades e pagamentos</h2>${visibleStudents().map(s=>{const f=feeFor(s.id);return `<div class="fee-row"><div><b>${esc(s.name)}</b><p>Previsto: ${money(f.expected)} · Recebido: ${money(f.received)}<br>Vencimento: dia ${f.due}</p></div><span class="tag ${feeOverdue(f)?'late-tag':''}">${!f.expected?'SEM VALOR':f.received>=f.expected?'PAGO':feeOverdue(f)?'VENCIDO':f.received?'PARCIAL':'A RECEBER'}</span><button onclick="editFee(${s.id})">Editar / registrar pagamento</button></div>`}).join('')}<p class="note">Controle demonstrativo local. O app não realiza cobranças, transferências ou pagamentos.</p></section>`}
function financeScreen(){return heading('GESTÃO DO PERSONAL','Seu tempo. Seus ganhos.','Organize atendimentos e acompanhe os valores de cada aluno.')+`<div class="training-tabs finance-tabs" role="tablist" aria-label="Gestão financeira"><button role="tab" aria-selected="${financeTab==='agenda'}" class="${financeTab==='agenda'?'primary':''}" onclick="setFinanceTab('agenda')">◷ Agenda presencial</button><button role="tab" aria-selected="${financeTab==='mensal'}" class="${financeTab==='mensal'?'primary':''}" onclick="setFinanceTab('mensal')">↗ Ganhos mensais</button></div><section role="tabpanel" aria-label="${financeTab==='agenda'?'Agenda presencial':'Ganhos mensais'}">${financeTab==='agenda'?agendaPanel():monthlyPanel()}</section>`}
window.setFinanceTab=tab=>{if(!['agenda','mensal'].includes(tab))return;financeTab=tab;render()};window.moveAgenda=direction=>{agendaOffset+=direction;render()};window.setFinanceMonth=value=>{if(!/^\d{4}-\d{2}$/.test(value))return;financeMonth=value;render()};
window.editAppointment=id=>{if(role!=='personal')return;const a=data.appointments.find(x=>x.id===id)||{student:(visibleStudents()[0]?.id||0),day:1,time:'08:00',duration:60,location:'',since:todayKey()};modal(`<h2>${id?'Editar atendimento':'Agendar atendimento'}</h2><form id="appointmentForm"><label>Aluno<select name="student">${visibleStudents().map(s=>`<option value="${s.id}" ${s.id===a.student?'selected':''}>${esc(s.name)}</option>`).join('')}</select></label><label>Dia da semana<select name="day">${weekdaysFull.map((day,i)=>`<option value="${i}" ${i===a.day?'selected':''}>${day}</option>`).join('')}</select></label><div class="inline"><label>Horário<input name="time" type="time" value="${a.time}" required></label><label>Duração (min)<input name="duration" type="number" min="10" max="240" value="${a.duration}" required></label></div><label>Começa em<input name="since" type="date" value="${a.since}" required></label><label>Local<input name="location" value="${esc(a.location)}" maxlength="120" placeholder="Academia, estúdio…"></label><p class="note">O atendimento se repete semanalmente até ser cancelado. Alerta 15 minutos antes, com o app aberto.</p><p id="appointmentError" role="alert" hidden></p><button class="primary">Salvar atendimento</button></form>`);$('#appointmentForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),value={id:id||crypto.randomUUID(),student:+f.get('student'),day:+f.get('day'),time:f.get('time'),duration:+f.get('duration'),since:f.get('since'),location:f.get('location').trim(),archived:false};if(value.duration<10||value.duration>240||minutesAt(value.time)+value.duration>1440)return;if(appointmentConflict(value,id)){$('#appointmentError').hidden=false;$('#appointmentError').textContent='Este horário coincide com outro atendimento. Escolha um horário livre.';return}const i=data.appointments.findIndex(x=>x.id===id);if(i<0)data.appointments.push(value);else data.appointments[i]=value;save();$('#modal').close();render();tickAppointments();toast('Atendimento semanal salvo.') }};
window.archiveAppointment=id=>{if(role!=='personal')return;const a=data.appointments.find(x=>x.id===id);if(a){a.archived=true;save();render();tickAppointments();toast('Programação cancelada.')}};
window.editFee=(id=(visibleStudents()[0]?.id||0))=>{if(role!=='personal')return;const month=financeMonth,f=feeFor(id,month);modal(`<h2>Valor mensal por aluno</h2><form id="feeForm"><label>Aluno<select name="student" onchange="editFee(Number(this.value))">${visibleStudents().map(s=>`<option value="${s.id}" ${s.id===id?'selected':''}>${esc(s.name)}</option>`).join('')}</select></label><p>Competência: ${month.slice(5)}/${month.slice(0,4)}</p><label>Valor previsto (R$)<input type="number" name="expected" min="0" max="1000000" step="0.01" value="${(f.expected/100).toFixed(2)}" required></label><label>Total já recebido no mês (R$)<input type="number" name="received" min="0" max="1000000" step="0.01" value="${(f.received/100).toFixed(2)}" required></label><label>Dia de vencimento<input name="due" type="number" min="1" max="31" value="${f.due}" required></label><p id="feeError" role="alert" hidden></p><button class="primary">Salvar valores</button></form>`);$('#feeForm').onsubmit=e=>{e.preventDefault();const values=new FormData(e.target),expected=Math.round(+values.get('expected')*100),received=Math.round(+values.get('received')*100),due=+values.get('due');if(!Number.isFinite(expected)||!Number.isFinite(received)||expected<0||received<0||due<1||due>31)return;if(received>expected){$('#feeError').hidden=false;$('#feeError').textContent='O recebido não pode ultrapassar o valor previsto. Ajuste o valor total previsto.';return}data.monthlyFees[month]??={};data.monthlyFees[month][id]={expected,received,due};save();$('#modal').close();render();toast('Valores mensais atualizados.')}};
const appointmentDock=document.createElement('section');appointmentDock.id='appointment-reminder';appointmentDock.hidden=true;document.body.append(appointmentDock);const reminded=new Set();
function upcomingAppointments(now=new Date()){const key=dayKey(now);return appointmentsOn(key).map(a=>({a,start:new Date(`${key}T${a.time}:00-03:00`).getTime()})).filter(x=>x.start>now.getTime()&&x.start-now.getTime()<=15*60000)}
window.enableAppointmentSound=()=>{try{const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio){toast('Som não disponível neste navegador. O alerta visual continua ativo.');return}appointmentAudio??=new Audio();appointmentAudio.resume().catch(()=>{});appointmentSound=true;render();toast('Som ativado para esta sessão.')}catch{toast('O navegador não permitiu ativar o som.')}};
function appointmentBeep(){if(!appointmentSound||appointmentAudio?.state!=='running')return;try{const o=appointmentAudio.createOscillator(),g=appointmentAudio.createGain();o.frequency.value=660;g.gain.value=.1;o.connect(g);g.connect(appointmentAudio.destination);o.start();g.gain.exponentialRampToValueAtTime(.001,appointmentAudio.currentTime+.6);o.stop(appointmentAudio.currentTime+.65)}catch{}}
function tickAppointments(){if(role!=='personal'||document.body.classList.contains('signed-out')){appointmentDock.hidden=true;return}const upcoming=upcomingAppointments();appointmentDock.hidden=!upcoming.length;if(!upcoming.length)return;appointmentDock.innerHTML=upcoming.map(({a,start})=>`<div role="alert"><span class="eyebrow">ATENDIMENTO EM ${Math.ceil((start-Date.now())/60000)} MIN</span><h3>${esc(appointmentName(a.student))} · ${a.time}</h3><p>${esc(a.location||'Atendimento presencial')} · Prepare-se para começar.</p><button onclick="go('financeiro');setFinanceTab('agenda')">Ver agenda</button></div>`).join('');upcoming.forEach(({a})=>{const key=`${todayKey()}-${a.id}-${a.time}`;if(!reminded.has(key)){reminded.add(key);appointmentBeep()}})}
setInterval(tickAppointments,10000);document.addEventListener('visibilitychange',tickAppointments);
const financeRender=render;render=function(){financeRender();if(role==='personal'){$('#nav').insertAdjacentHTML('beforeend',`<button class="${page==='financeiro'?'active':''}" onclick="go('financeiro')">◷ &nbsp; Gestão financeira</button>`);if(page==='financeiro')$('#content').innerHTML=financeScreen()}tickAppointments()};

